<span class="line"><span style="color:#ABB2BF;">            from_balance </span><span style="color:#56B6C2;">=</span><span style="color:#56B6C2;"> int</span><span style="color:#ABB2BF;">(pipe.</span><span style="color:#61AFEF;">get</span><span style="color:#ABB2BF;">(from_key) </span><span style="color:#C678DD;">or</span><span style="color:#D19A66;"> 0</span><span style="color:#ABB2BF;">)</span></span>
